// ============================================================
// DATA VALIDATION: Проверка данных перед скорингом
// ============================================================

const input = $json;
const data = input.extracted_data || input.known_data || {};

const hasName = data.first_name && data.first_name !== null;
const hasAge = data.age && !isNaN(parseInt(data.age));
const hasPhone = data.phone && data.phone !== null;
const hasCitizenship = data.citizenship && data.citizenship !== null;

const isValid = hasName && hasAge && hasPhone;

return {
  ...input,
  extracted_data: data,
  is_valid: isValid,
  validation_errors: {
    missing_name: !hasName,
    missing_age: !hasAge,
    missing_phone: !hasPhone,
    missing_citizenship: !hasCitizenship
  }
};

// ============================================================
// SCORING ENGINE: Multi-Factor Score (FIXED)
// Возраст строго < 50 лет согласно ТЗ
// ============================================================

const input = $json;
const data = input.extracted_data || {};

let score = 0;
const breakdown = {
  documents: 0,
  experience: 0,
  age: 0,
  russian_level: 0,
  communication: 0
};

// 1. DOCUMENTS (0-25)
const docStatus = String(data.documents_status || '').toLowerCase();
const hasAmina = data.has_amina_app === true;

if (hasAmina) {
  breakdown.documents = 25;
} else if (['yes', 'да', 'есть', 'complete'].includes(docStatus)) {
  breakdown.documents = 25;
} else if (['partial', 'частично'].includes(docStatus)) {
  breakdown.documents = 15;
} else if (['processing', 'оформляю', 'в процессе'].includes(docStatus)) {
  breakdown.documents = 10;
} else if (['no', 'нет', 'missing'].includes(docStatus)) {
  breakdown.documents = 0;
} else {
  breakdown.documents = 5;
}
score += breakdown.documents;

// 2. EXPERIENCE (0-25)
const expText = String(data.experience || '').toLowerCase();
const expMatch = expText.match(/(\d+)/);
const expYears = expMatch ? parseInt(expMatch[1]) : 0;

if (expYears >= 5) breakdown.experience = 25;
else if (expYears >= 3) breakdown.experience = 20;
else if (expYears >= 1) breakdown.experience = 15;
else if (expText.includes('есть') || expText.includes('работал') || expText.length > 10) breakdown.experience = 12;
else breakdown.experience = 5;
score += breakdown.experience;

// 3. AGE (0-25) — СТРОГО до 50 лет!
const age = parseInt(data.age) || 0;
if (age > 0 && age <= 30) breakdown.age = 25;
else if (age > 30 && age <= 40) breakdown.age = 20;
else if (age > 40 && age <= 45) breakdown.age = 15;
else if (age > 45 && age < 50) breakdown.age = 10;
else if (age >= 50) breakdown.age = 0; // ОТКАЗ
else breakdown.age = 10;
score += breakdown.age;

// 4. RUSSIAN LEVEL (0-15)
const russianLevel = String(data.russian_level || '').toLowerCase();
if (['хороший', 'отличный', 'свободный', 'good'].includes(russianLevel)) {
  breakdown.russian_level = 15;
} else if (['базовый', 'средний', 'basic'].includes(russianLevel)) {
  breakdown.russian_level = 10;
} else if (['слабый', 'начальный', 'poor'].includes(russianLevel)) {
  breakdown.russian_level = 5;
} else {
  breakdown.russian_level = 8;
}
score += breakdown.russian_level;

// 5. COMMUNICATION (0-10)
breakdown.communication = 10;
score += breakdown.communication;

// DETERMINE RECOMMENDATION
let recommendation = 'manual_review';
let rejectionReason = null;

if (age >= 50) {
  recommendation = 'auto_reject';
  rejectionReason = 'age';
} else if (!hasAmina && ['no', 'нет', 'missing'].includes(docStatus)) {
  recommendation = 'ask_documents';
  rejectionReason = 'documents';
} else if (['processing', 'оформляю'].includes(docStatus)) {
  recommendation = 'documents_pending';
} else if (score >= 65) {
  recommendation = 'auto_approve';
} else if (score >= 45) {
  recommendation = 'manual_review';
} else {
  recommendation = 'auto_reject';
  rejectionReason = 'low_score';
}

return {
  ...input,
  final_score: score,
  score_breakdown: breakdown,
  recommendation: recommendation,
  rejection_reason: rejectionReason,
  has_amina_app: hasAmina
};

// Invalid data - return to interview
const input = $json;
const errors = input.validation_errors || {};

let missing = [];
if (errors.missing_name) missing.push('имя');
if (errors.missing_age) missing.push('возраст');
if (errors.missing_phone) missing.push('телефон');

return {
  ...input,
  recommendation: 'return_to_interview',
  missing_fields: missing
};

